package com.donutsmp.gamehub.config;
import com.donutsmp.gamehub.game.Game;import java.util.*;import java.util.regex.Pattern;
public record HubConfig(long minimumBet,long maximumBet,String paymentTarget,Set<String> enabledGames,boolean showOdds,Map<String,Long> cratePrices){private static final Pattern NAME=Pattern.compile("^\\.?[A-Za-z0-9_]{3,16}$");public static HubConfig validated(long min,long max,String target,Set<String> enabled,boolean showOdds,Map<String,Long> crates){if(min<=0||max<min||target==null||!NAME.matcher(target).matches())throw new IllegalArgumentException("Invalid backend config");return new HubConfig(min,max,target,Set.copyOf(enabled),showOdds,Map.copyOf(crates));}public boolean isEnabled(Game game){return enabledGames.contains(game.id());}public String payCommand(){return "/pay "+paymentTarget;}}
